<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {useRoute} from 'vue-router'
import {api,requestKey} from '../api/client'
import {names,type Attempt} from '../types'
import TaskProblem from '../components/TaskProblem.vue'
import WorkedExplanation from '../components/WorkedExplanation.vue'
const route=useRoute(),attempt=ref<Attempt|null>(null),thread=ref<{messages:{message:string;reply:string}[];approved:boolean;provider_status:string;remaining_today:number;message:string}|null>(null),message=ref(''),includeScratchpad=ref(false),busy=ref(false),error=ref(''),requestId=ref('')
async function load(){attempt.value=await api<Attempt>('/attempts/'+route.params.id);if(!attempt.value.sealed)thread.value=await api('/attempts/'+route.params.id+'/discussion')}
async function send(suggestion?:string){if(busy.value)return;if(suggestion)message.value=suggestion;if(!message.value.trim())return;busy.value=true;error.value='';try{if(!requestId.value)requestId.value=requestKey();await api('/attempts/'+route.params.id+'/discussion','POST',{message:message.value,include_scratchpad:includeScratchpad.value},requestId.value);message.value='';requestId.value='';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function edited(){requestId.value=''}
async function clear(){if(!confirm('Clear this discussion? The graded attempt and quota records remain saved.'))return;try{await api('/attempts/'+route.params.id+'/discussion','DELETE',{confirm:true});await load()}catch(e){error.value=(e as Error).message}}
onMounted(async()=>{try{await load()}catch(e){error.value=(e as Error).message}})
</script>
<template><span class="eyebrow">A CONVERSATION AFTER THE ATTEMPT</span><h1>Let’s work through it.</h1><p class="lead">Your original answer stays the same. Your understanding can change.</p><div v-if="error" class="error" role="alert">{{error}}</div><p v-if="attempt?.sealed" class="notice">Assessment discussion is sealed. Complete the check and explicitly release its content first.</p><div v-else-if="attempt" class="discussion-layout"><section class="panel context-panel"><span class="eyebrow">{{names[attempt.family]}} / LEVEL {{attempt.difficulty}}</span><h2>{{attempt.task?.instructions}}</h2><TaskProblem v-if="attempt.task" :task="attempt.task" :model-value="attempt.answer??null" locked/><details><summary>Read the deterministic worked solution</summary><WorkedExplanation v-if="attempt.explanation" :explanation="attempt.explanation"/></details><RouterLink :to="'/review/'+attempt.id">Back to this attempt ↗</RouterLink></section><section class="panel conversation"><div class="section-heading"><h2>Discussion</h2><button class="text-button" v-if="thread?.messages.length" @click="clear">Clear thread</button></div><p class="privacy-note">{{thread?.message}}</p><div v-if="thread&&!thread.approved" class="locked-state"><span class="eyebrow">OWNER INVITATION REQUIRED</span><h3>Your worked solution is always open.</h3><p>Optional AI discussion needs an active owner-issued grant. Redeem your invitation in Settings.</p><RouterLink class="button" to="/settings">Open AI access →</RouterLink></div><div v-else-if="thread?.provider_status!=='configured'" class="locked-state"><h3>AI discussion is {{thread?.provider_status??'unavailable'}}.</h3><p>No model request has been made. Use the worked solution beside this panel.</p></div><template v-else><p class="micro">{{thread.remaining_today}} REQUEST(S) REMAIN TODAY</p><div class="messages" aria-live="polite"><div v-for="(m,i) in thread.messages" :key="i" class="message-pair"><span class="eyebrow">YOU</span><p>{{m.message}}</p><span class="eyebrow">TUTOR</span><p class="tutor-message">{{m.reply}}</p></div><p v-if="!thread.messages.length" class="empty-inline">Ask about a step, test an alternative, or explain where you got stuck.</p></div><div class="suggestions"><button v-for="s in ['Explain what the question is asking.','Why is my answer correct or incorrect?','Show me a concrete example.']" :key="s" @click="send(s)" :disabled="busy">{{s}}</button></div><form @submit.prevent="send()"><label>Your question<textarea v-model="message" @input="edited" maxlength="2000" rows="4" placeholder="Here is how I reasoned about it…" :disabled="busy"></textarea></label><label class="checkbox"><input v-model="includeScratchpad" @change="edited" type="checkbox" :disabled="busy">Include this attempt’s scratchpad in the provider context.</label><button class="primary" :disabled="busy||!message.trim()">{{busy?'Waiting for tutor…':'Send question →'}}</button></form></template></section></div></template>
